-- LOCAL DEMO ONLY: approximate copies of the existing Dynasty FC tables so the site can run on SQLite.
CREATE TABLE IF NOT EXISTS users (user_id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT, password_hash TEXT, email TEXT UNIQUE, role TEXT, is_active INT DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS players (player_id INTEGER PRIMARY KEY AUTOINCREMENT, mysafa_id TEXT UNIQUE, first_name TEXT, last_name TEXT, date_of_birth TEXT, position TEXT, contact_email TEXT, contact_phone TEXT, team_group TEXT, age_group TEXT, jersey_number INT, is_injured INT DEFAULT 0, is_active INT DEFAULT 1);
CREATE TABLE IF NOT EXISTS messages (message_id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, email TEXT, subject TEXT, message TEXT, is_read INT DEFAULT 0, created_at TEXT);
CREATE TABLE IF NOT EXISTS volunteer_applications (volunteer_id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, email TEXT, phone TEXT, role TEXT, availability TEXT, message TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS newsletters (newsletter_id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, content TEXT, image_url TEXT, is_published INT DEFAULT 1, created_by INT, published_at TEXT DEFAULT CURRENT_TIMESTAMP, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS testimonials (testimonial_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INT, author_name TEXT, author_role TEXT, content TEXT, status TEXT, approved_by INT, approved_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gallery_photos (photo_id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, caption TEXT, team_group TEXT, file_path TEXT, uploaded_by INT, uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS team_matches (match_id INTEGER PRIMARY KEY AUTOINCREMENT, team_group TEXT, age_group TEXT, home_team TEXT, away_team TEXT, match_date TEXT, match_time TEXT, venue TEXT, home_score INT, away_score INT, is_completed INT DEFAULT 0, created_by INT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS match_predictions (prediction_id INTEGER PRIMARY KEY AUTOINCREMENT, match_id INT, user_id INT, home_score INT, away_score INT, points INT, predicted_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS staff (staff_id INTEGER PRIMARY KEY AUTOINCREMENT, first_name TEXT, last_name TEXT, role TEXT, employment_status TEXT, contact_email TEXT, contact_phone TEXT, date_joined TEXT);
CREATE TABLE IF NOT EXISTS vw_finance_dashboard (month TEXT, description TEXT, income REAL, expenses REAL);
CREATE TABLE IF NOT EXISTS inventory_items (item_id INTEGER PRIMARY KEY AUTOINCREMENT, item_name TEXT, category TEXT, quantity INT, item_condition TEXT, storage_location TEXT, purchase_date TEXT, purchase_cost REAL);
CREATE TABLE IF NOT EXISTS donations (donation_id INTEGER PRIMARY KEY AUTOINCREMENT, donor_name TEXT, donor_email TEXT, donor_phone TEXT, amount REAL, message TEXT, is_anonymous INT DEFAULT 0, payment_status TEXT, payment_ref TEXT, paid_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents_vault (document_id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, file_name TEXT, file_path TEXT, document_type TEXT, description TEXT, uploaded_by INT, uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS match_votes (vote_id INTEGER PRIMARY KEY AUTOINCREMENT, match_id INT, user_id INT, vote TEXT);
